use super::*;
pub const NOTIFICATION_SOURCES: &str = "chariox.notification_sources";
pub const NOTIFICATION_SUBSCRIBE: &str = "chariox.notification_subscribe";
pub const NOTIFICATION_UNSUBSCRIBE: &str = "chariox.notification_unsubscribe";
pub const WATCHER_CREATE: &str = "chariox.watcher.create";
pub const WATCHER_DRY_RUN: &str = "chariox.watcher.dry_run";
pub const WATCHER_ACTIVATE: &str = "chariox.watcher.activate";
pub const WATCHER_STATUS: &str = "chariox.watcher.status";
pub const WATCHER_REMOVE: &str = "chariox.watcher.remove";

pub fn notification_tool_specs() -> Vec<RuntimeToolSpec> {
    vec![
        RuntimeToolSpec { name: NOTIFICATION_SOURCES.into(), description: "List this Room's workflow exit notifications and installed Apps' outgoing events, and for the Room owner's own agents the owner's workflow sources on its other kernels. Source identities grant no App capability or access to other Rooms.".into(), input_schema: serde_json::json!({"type":"object","properties":{},"additionalProperties":false}) },
        RuntimeToolSpec { name: NOTIFICATION_SUBSCRIBE.into(), description: "Subscribe yourself to one source returned by notification_sources. Every occurrence queues a prompt; there is no delivery policy. The queued row's Steer sends it into the running turn. No other agent can be named.".into(), input_schema: serde_json::json!({"type":"object","required":["source"],"properties":{"source":{"oneOf":[{"type":"object","required":["workflow"],"properties":{"workflow":{"type":"object","required":["source_id"],"properties":{"source_id":{"type":"string"}},"additionalProperties":false}},"additionalProperties":false},{"type":"object","required":["app"],"properties":{"app":{"type":"object","required":["installation_id","event_name"],"properties":{"installation_id":{"type":"string"},"event_name":{"type":"string"}},"additionalProperties":false}},"additionalProperties":false}]},"prompt":{"type":"string"}},"additionalProperties":false}) },
        RuntimeToolSpec { name: WATCHER_CREATE.into(), description: "Create a watcher: a script this kernel runs as a notification source of the Room owner, or change one (pass watcher_id; a change returns it to draft). The script reads one JSON line on stdin, {\"cursor\":<what it last wrote>|null,\"now_ms\":n,\"dry_run\":bool,\"since_ms\":n|null}, and writes JSON lines on stdout: {\"reading\":\"what it sees now, in words\"}, {\"event\":\"<declared name>\",\"key\":\"<only for keyed events>\",\"text\":\"the message subscribers get\"}, {\"history\":false} when what it watches keeps no history, and {\"cursor\":<any JSON, 64 KiB at most>} as its only memory. A poll run commits its events and cursor when it exits with 0; a stream commits at each cursor line. When dry_run is true, report what would have fired since since_ms. The script runs from its own directory; command is its argv (for example [\"python3\",\"watch.py\"]). Nothing runs until chariox.watcher.dry_run passed and chariox.watcher.activate turned it on. Subscribe with chariox.notification_subscribe {source:{workflow:{source_id}}}.".into(), input_schema: serde_json::json!({"type":"object","required":["manifest","script"],"properties":{"watcher_id":{"type":"string"},"manifest":{"type":"object","required":["name","sentence","mode","command","events"],"properties":{"name":{"type":"string","description":"Short name the person sees"},"sentence":{"type":"string","description":"One line the person sees, e.g. 'Watching the X100VI page at fotokoch.de every 30 min'"},"mode":{"oneOf":[{"type":"object","required":["poll"],"properties":{"poll":{"type":"object","required":["every_s"],"properties":{"every_s":{"type":"integer","minimum":60}},"additionalProperties":false}},"additionalProperties":false},{"const":"stream"}]},"command":{"type":"array","items":{"type":"string"},"minItems":1},"events":{"type":"array","minItems":1,"items":{"type":"object","required":["name"],"properties":{"name":{"type":"string"},"keyed":{"type":"boolean"}},"additionalProperties":false}},"coalesce":{"enum":["every","latest_per_key"]},"debounce_s":{"type":"integer","minimum":0}},"additionalProperties":false},"script":{"type":"object","required":["file_name","text"],"properties":{"file_name":{"type":"string"},"text":{"type":"string"}},"additionalProperties":false}},"additionalProperties":false}) },
        RuntimeToolSpec { name: WATCHER_DRY_RUN.into(), description: "Run a watcher once with dry_run true and since_ms 24 hours back. Nothing is committed or delivered; returns its reading, whether its source keeps history and the events it would have fired. Passing it is what allows chariox.watcher.activate for this version.".into(), input_schema: serde_json::json!({"type":"object","required":["watcher_id"],"properties":{"watcher_id":{"type":"string"}},"additionalProperties":false}) },
        RuntimeToolSpec { name: WATCHER_ACTIVATE.into(), description: "Turn a watcher on after its dry run passed, or pause it (paused: true) and turn it on again.".into(), input_schema: serde_json::json!({"type":"object","required":["watcher_id"],"properties":{"watcher_id":{"type":"string"},"paused":{"type":"boolean"}},"additionalProperties":false}) },
        RuntimeToolSpec { name: WATCHER_STATUS.into(), description: "The owner's watchers on this kernel, or one with its health, reading and the end of its last failed run's error output.".into(), input_schema: serde_json::json!({"type":"object","properties":{"watcher_id":{"type":"string"}},"additionalProperties":false}) },
        RuntimeToolSpec { name: WATCHER_REMOVE.into(), description: "Remove a watcher: it stops and its notification source ends.".into(), input_schema: serde_json::json!({"type":"object","required":["watcher_id"],"properties":{"watcher_id":{"type":"string"}},"additionalProperties":false}) },
        RuntimeToolSpec { name: NOTIFICATION_UNSUBSCRIBE.into(), description: "Delete one of your own notification triggers and detach its subscription. Accepts only the trigger_id returned by notification_subscribe.".into(), input_schema: serde_json::json!({"type":"object","required":["trigger_id"],"properties":{"trigger_id":{"type":"string"}},"additionalProperties":false}) },
    ]
}
